from functools import lru_cache

class Solution:
    def stoneGameVI(self, aliceValues: List[int], bobValues: List[int]) -> int:
        n = len(aliceValues)

        @lru_cache(maxsize=None)
        def adv(mask):
            if mask == (1 << n) - 1:
                return 0
            alice_turn = bin(mask).count('1') % 2 == 0
            best = -float('inf')
            for i in range(n):
                if not mask >> i & 1:
                    gain = aliceValues[i] if alice_turn else bobValues[i]
                    best = max(best, gain - adv(mask | 1 << i))
            return best

        score = adv(0)
        return 1 if score > 0 else (-1 if score < 0 else 0)

