class Solution {
    private int n;
    private int[] a, b;
    private Map<Integer, Integer> memo = new HashMap<>();

    public int stoneGameVI(int[] aliceValues, int[] bobValues) {
        a = aliceValues;
        b = bobValues;
        n = a.length;
        int score = adv(0);
        return score > 0 ? 1 : (score < 0 ? -1 : 0);
    }

    private int adv(int mask) {
        if (mask == (1 << n) - 1) return 0;
        Integer cached = memo.get(mask);
        if (cached != null) return cached;
        boolean aliceTurn = Integer.bitCount(mask) % 2 == 0;
        int best = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            if ((mask >> i & 1) == 0) {
                int gain = aliceTurn ? a[i] : b[i];
                best = Math.max(best, gain - adv(mask | 1 << i));
            }
        }
        memo.put(mask, best);
        return best;
    }
}

