    const n = aliceValues.length;
    const bitCount = (x) => { let c = 0; while (x) { x &= x - 1; c++; } return c; };
    const memo = new Map();
    const adv = (mask) => {
        if (mask === (1 << n) - 1) return 0;
        if (memo.has(mask)) return memo.get(mask);
        const aliceTurn = bitCount(mask) % 2 === 0;
        let best = -Infinity;
        for (let i = 0; i < n; i++) {
            if (!(mask >> i & 1)) {
                const gain = aliceTurn ? aliceValues[i] : bobValues[i];
                best = Math.max(best, gain - adv(mask | (1 << i)));
            }
        }
        memo.set(mask, best);
        return best;
    };
    const score = adv(0);
    return score > 0 ? 1 : (score < 0 ? -1 : 0);
};

